head.script:
scwin.onpageload = function() {
	var jsonData = [{col1:"a", "col2":"1"},{col1:"b", "col2":"2"},{col1:"c", "col2":"3"},{col1:"d", "col2":"4"}
                    ,{col1:"d", "col2":"5"},{col1:"d", "col2":"6"},{col1:"d", "col2":"7"},{col1:"d", "col2":"8"}
                    ,{col1:"d", "col2":"9"},{col1:"a", "col2":"10"}];
    dataList1.setJSON(jsonData);

	var jsonData2 = [{col1:"a", "col2":"tab2_1"},{col1:"b", "col2":"2"},{col1:"c", "col2":"3"},{col1:"d", "col2":"4"}
                    ,{col1:"d", "col2":"5"},{col1:"d", "col2":"6"},{col1:"d", "col2":"7"},{col1:"a", "col2":"8"}
                    ,{col1:"d", "col2":"9"},{col1:"a", "col2":"10"}];
    dataList2.setJSON(jsonData2);                
	var jsonData3 = [{col1:"a", "col2":"tab3_1"},{col1:"b", "col2":"2"},{col1:"c", "col2":"3"},{col1:"d", "col2":"4"}
                    ,{col1:"d", "col2":"5"},{col1:"d", "col2":"6"},{col1:"d", "col2":"7"},{col1:"d", "col2":"8"}
                    ,{col1:"d", "col2":"9"},{col1:"a", "col2":"10"}];
    dataList3.setJSON(jsonData3);
};

scwin.gridView1_customFormatter = function (data, formattedData, rowIndex, columnIndex) {
    if(data == "a"){
        gridView1.setRowClass(rowIndex, "test1");
    }

    return data;
};
scwin.gridView2_customFormatter = function (data, formattedData, rowIndex, columnIndex) {
    if(data == "a"){
        gridView2.setRowClass(rowIndex, "test1");
    }
    return data;
};
scwin.gridView3_customFormatter = function (data, formattedData, rowIndex, columnIndex) {
	if(data == "a"){
        gridView3.setRowClass(rowIndex, "test1");
    }else if(data == "d"){
        gridView3.setCellColor(rowIndex, 0, "blue")
    }
    return data;
};


scwin.trigger1_onclick = function(e){
    var options = { 

                common: { 
                    fileName : "multi_tabControl_gridView.xlsx", 
                    showProcess : true, 
                    rowsByN:"10000",
                    printSet : { 
                        landScape : "true", 
                        fitToPage : "true", 
                        fitWidth : "4", 
                        fitHeight : "333", 
                        scale : "222" 
                    }
                }, 
                excelInfo: [ 
                    { 
                        gridId : "gridView1", 
                        sheetName : "첫번째 sheet", 
                        type : "1", 
                        useClass : "true",
                        useStyle : "true",
                        removeColumns : "", 
                        foldColumns : "", 
                        startRowIndex : 6, 
                        startColumnIndex : 0
                    }, 
                    { 
                        gridId : "gridView2", 
                        sheetName : "두번째 sheet", 
                        type : "1", 
                        useClass : "true",
                        useStyle : "true",
                        removeColumns : "", 
                        foldColumns : "", 
                        startRowIndex : 3, 
                        startColumnIndex : 0
                    }, 
                    { 
                        gridId : "gridView3", 
                        sheetName : "sheet3", 
                        type : "1", 
                        useClass : "true",
                        useStyle : "true",
                        removeColumns : "", 
                        foldColumns : "", 
                        startRowIndex : 3, 
                        startColumnIndex : 0
                    } 
                ] 
            }; 
            $p.multipleExcelDownload( options );
        }
